Action<string,Renderer,Vector3,float> orbit=(n,r,dir,height)=>{if(!r)return;var b=r.bounds;var center=b.center;center.y=Mathf.Max(b.min.y+4,b.center.y-3);float dist=Mathf.Max(b.extents.x,b.extents.z)*1.65f+24;if(n=="Bus terminal"||n=="Parking plaza")dist=Mathf.Abs(dir.x)*b.extents.x+Mathf.Abs(dir.z)*b.extents.z+40;var side=Vector3.Cross(dir,Vector3.up).normalized;shots.Add(new Shot(n,center+dir*dist+side*11+Vector3.up*height,center+dir*(dist*.87f)-side*11+Vector3.up*(height*.78f),center,center));};
