var bridge=rs.Where(r=>r.name=="Mobile bridge LED strips"&&r.bounds.size.y>25&&r.bounds.extents.x>60&&r.bounds.extents.z<30).OrderByDescending(r=>r.bounds.size.x+r.bounds.size.z).FirstOrDefault();if(bridge){var b=bridge.bounds;var along=b.size.x>b.size.z?Vector3.right:Vector3.forward;float span=Mathf.Max(b.extents.x,b.extents.z);var cross=Vector3.Cross(along,Vector3.up);var c=b.center;orbit("Bridge approach",bridge,cross,15);var road=rs.Where(r=>r.bounds.size.y<8&&r.bounds.size.x>10&&r.bounds.size.z>10).OrderBy(r=>Vector2.Distance(new Vector2(r.bounds.center.x,r.bounds.center.z),new Vector2(c.x,c.z))).First();float y=b.min.y+6;var start=c-along*span*.70f;var end=c+along*span*.70f;start.y=end.y=y;shots.Add(new Shot("Through the bridge",start,end,start+along*80,end+along*80));}else orbit("City avenue",hospital,Vector3.right,35);
