var go=new GameObject("Temporary cinematic export camera"){hideFlags=HideFlags.HideAndDontSave};cam=go.AddComponent<Camera>();cam.enabled=false;cam.fieldOfView=62;cam.nearClipPlane=.3f;cam.farClipPlane=3500;cam.allowHDR=true;cam.clearFlags=CameraClearFlags.Skybox;var data=cam.GetUniversalAdditionalCameraData();data.renderPostProcessing=true;data.volumeLayerMask=1;data.volumeTrigger=go.transform;data.antialiasing=AntialiasingMode.SubpixelMorphologicalAntiAliasing;data.antialiasingQuality=AntialiasingQuality.High;rt=new RenderTexture(W,H,24,RenderTextureFormat.ARGB32);rt.Create();cam.targetTexture=rt;frame=new Texture2D(W,H,TextureFormat.RGBA32,false);index=0;var vg=new GameObject("Temporary film grade"){hideFlags=HideFlags.HideAndDontSave};grade=vg.AddComponent<Volume>();grade.isGlobal=true;grade.priority=1000;grade.profile=ScriptableObject.CreateInstance<VolumeProfile>();var ca=grade.profile.Add<ColorAdjustments>();filmColor=ca;ca.postExposure.Override(.25f);ca.contrast.Override(12);ca.saturation.Override(-5);var vi=grade.profile.Add<Vignette>();vi.intensity.Override(.18f);vi.smoothness.Override(.45f);
if(!preview)encoder=new MediaEncoder(Path.GetFullPath(D+"/Gangstar-City-Cinematic-1080p.mp4"),new VideoTrackAttributes{frameRate=new MediaRational(FPS),width=W,height=H,includeAlpha=false,bitRateMode=VideoBitrateMode.High},new AudioTrackAttributes{channelCount=2,sampleRate=new MediaRational(48000),language=""});File.WriteAllText(D+"/Status.txt","Rendering "+(preview?"shot previews":"1080p / 30fps / 120 seconds"));}
static void Render(){float t=preview?(index/3)*7.5f+new[]{.05f,3.75f,7.45f}[index%3]:index/(float)FPS;int shot=Mathf.Min(15,(int)(t/7.5f));float u=(t-shot*7.5f)/7.5f;float ease=u;var s=shots[shot];float night=Mathf.SmoothStep(0,1,Mathf.Clamp01((t-30)/40));ctrl.SetManualBlend(night);float fade=Mathf.Min(Mathf.Clamp01(t/1.2f),Mathf.Clamp01((120-t)/2));filmColor.postExposure.value=.25f-(1-fade)*9;cam.transform.position=Vector3.Lerp(s.a,s.b,ease)+Vector3.Cross((s.b-s.a).normalized,Vector3.up)*Mathf.Sin(u*Mathf.PI)*3;cam.transform.LookAt(Vector3.Lerp(s.ta,s.tb,ease));bool fast=s.name.Contains("Rush")||s.name.Contains("Under");cam.fieldOfView=fast?Mathf.Lerp(68,78,u):s.name.Contains("Close")?Mathf.Lerp(49,54,u):62;cam.transform.rotation*=Quaternion.Euler(0,0,(fast?5.0f:2.0f)*Mathf.Sin((u-.5f)*Mathf.PI));ctrl.RefreshStreetLights(cam);VolumeManager.instance.Update(cam.transform,1);cam.Render();var prior=RenderTexture.active;RenderTexture.active=rt;frame.ReadPixels(new Rect(0,0,W,H),0,0);frame.Apply();RenderTexture.active=prior;
