shots.Add(new Shot("Bridge lights rotating sweep",c+new Vector3(95,23,90),c+new Vector3(-95,30,100),c-Vector3.up*8,c-Vector3.up*8));shots.Add(new Shot("Night skyline motion",new Vector3(70,185,630),new Vector3(420,185,650),new Vector3(100,50,60),new Vector3(350,50,30)));
