var log=new List<string>();for(int k=0;k<shots.Count;k++){var s=shots[k];int hits=0;for(int n=0;n<=90;n++){float u=n/90f;var p=Vector3.Lerp(s.a,s.b,u)+Vector3.Cross((s.b-s.a).normalized,Vector3.up)*Mathf.Sin(u*Mathf.PI)*3;if(solids.Any(bb=>bb.Contains(p)))hits++;}log.Add(s.name+": building-volume intersections="+hits);if(hits>0){float top=0;foreach(var bb in solids)for(int n=0;n<=90;n++){var p=Vector3.Lerp(s.a,s.b,n/90f);if(p.x>=bb.min.x-4&&p.x<=bb.max.x+4&&p.z>=bb.min.z-4&&p.z<=bb.max.z+4)top=Mathf.Max(top,bb.max.y+12);}s.a.y=Mathf.Max(s.a.y,top);s.b.y=Mathf.Max(s.b.y,top);shots[k]=s;log.Add("Corrected camera height="+top);}}File.WriteAllLines(D+"/PathCheck.txt",log);}
static void Close(string n,Renderer r,Vector3 front,float dist,float height,float travel){var c=r.bounds.center;c.y=r.bounds.min.y+7;var side=Vector3.Cross(front,Vector3.up);shots.Add(new Shot(n,c+front*dist-side*travel+Vector3.up*height,c+front*(dist-4)+side*travel+Vector3.up*(height+3),c,c+Vector3.up*2));}
static void Track(string name,Renderer r,Vector3 front,float distance,float height,float travel){var c=r.bounds.center;c.y=Mathf.Max(r.bounds.min.y+6,c.y-3);var side=Vector3.Cross(front,Vector3.up);shots.Add(new Shot(name,c+front*distance-side*travel+Vector3.up*height,c+front*(distance-8)+side*travel+Vector3.up*(height+2),c-side*7,c+side*7));}
static readonly double[] MusicRoots={41.2034446,32.7031957,48.9994295,36.70809599};static readonly int[] Riff={0,0,7,0,10,7,3,7,0,12,7,10,3,7,10,14};
static double Noise(double x){double q=Math.Sin(x*127.1+311.7)*43758.5453;return (q-Math.Floor(q))*2-1;}
