static Vector2 Music(double t){double beat=t*128/60,phase=beat-Math.Floor(beat),eight=beat*2-Math.Floor(beat*2),sixteen=beat*4-Math.Floor(beat*4);int bar=(int)(beat/4),chord=(bar/2)%4;double root=MusicRoots[chord];double third=chord==0?1.189207115:1.25992105;double drop=t>=30&&t<60||t>=75?1:.60;double fade=Math.Min(1,t/1.2)*Math.Min(1,(120-t)/2);double intro=Math.Min(1,t/7.5);double l=0,r=0;
