double side=.35+.65*(1-Math.Exp(-phase*7));foreach(double ratio in new[]{2.0,third*2,3.0,4.0}){double f=root*ratio;l+=(Math.Sin(2*Math.PI*f*t)+.3*Math.Sin(2*Math.PI*f*1.003*t)+.15*Math.Sin(2*Math.PI*f*2*t))*.025*side;r+=(Math.Sin(2*Math.PI*f*t+.15)+.3*Math.Sin(2*Math.PI*f*.997*t)+.15*Math.Sin(2*Math.PI*f*2*t+.4))*.025*side;}
double bassHz=root*(phase>.74?2:1);double bass=(Math.Sin(2*Math.PI*bassHz*t)+.28*Math.Sin(2*Math.PI*bassHz*2*t)+.12*Math.Sin(2*Math.PI*bassHz*3*t))*(.55+.45*Math.Exp(-eight*6))*.16*side*drop;
