// Punchy electronic kick, layered backbeat, closed hats and occasional open hats.
double sec=phase*60/128;double kick=Math.Sin(2*Math.PI*(47*sec+2.7*(1-Math.Exp(-sec*40))))*Math.Exp(-sec*11)*.31;double click=Noise(Math.Floor(t*48000))*Math.Exp(-sec*180)*.035;double snare=((int)beat%4==1||(int)beat%4==3)?(Noise(Math.Floor(t*48000))*.16+Math.Sin(2*Math.PI*185*t)*.07)*Math.Exp(-sec*19):0;double hats=Noise(Math.Floor(t*48000)+72)*Math.Exp(-sixteen*33)*.024;double open=(int)(beat*2)%4==3?Noise(Math.Floor(t*48000)+165)*Math.Exp(-eight*8)*.025:0;double drums=(kick+click+snare+hats+open)*intro*drop;
