double build=t>67.5&&t<75?(t-67.5)/7.5:0;double riser=Noise(Math.Floor(t*24000)+79)*build*build*.055;double cut=t%7.5;double swish=Noise(Math.Floor(t*16000)+188)*Math.Exp(-cut*8)*.024;double gain=1.5;return new Vector2((float)(Math.Tanh((l+bass+drums+riser+swish)*gain)*.9*fade),(float)(Math.Tanh((r+bass+drums+riser+swish*.75)*gain)*.9*fade));}

